import{_ as e,o as r,c as t,a4 as o}from"./chunks/framework.CSpBcIj4.js";const u=JSON.parse('{"title":"プライバシーポリシー","description":"Sapphire Star Codex のアプリとウェブサイトに関するプライバシーポリシー。保存データ、バックアップ、お問い合わせ、削除について。","frontmatter":{"description":"Sapphire Star Codex のアプリとウェブサイトに関するプライバシーポリシー。保存データ、バックアップ、お問い合わせ、削除について。","head":[["link",{"rel":"canonical","href":"https://eurekaffeine.github.io/sapphire-star-codex/ja-jp/privacy/"}],["meta",{"property":"og:url","content":"https://eurekaffeine.github.io/sapphire-star-codex/ja-jp/privacy/"}],["meta",{"property":"og:title","content":"プライバシーポリシー | Sapphire Star Codex"}],["meta",{"property":"og:description","content":"Sapphire Star Codex のアプリとウェブサイトに関するプライバシーポリシー。保存データ、バックアップ、お問い合わせ、削除について。"}]]},"headers":[],"relativePath":"ja-jp/privacy/index.md","filePath":"ja-jp/privacy/index.md"}'),i={name:"ja-jp/privacy/index.md"};function n(l,a,p,h,s,c){return r(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="プライバシーポリシー" tabindex="-1">プライバシーポリシー <a class="header-anchor" href="#プライバシーポリシー" aria-label="Permalink to &quot;プライバシーポリシー&quot;">​</a></h1><p>施行日・最終更新日：2026年10月31日</p><p>このポリシーは、Sapphire Star Codex（日本語名「青い星のハンターノート」）の iOS、Android、HarmonyOS アプリと、このウェブサイトに適用されます。開発者は <strong>eurekaffeine（刘耀晨）</strong> です。プライバシーに関するお問い合わせは <a href="mailto:eurekaffeine.work@gmail.com" target="_blank" rel="noreferrer">eurekaffeine.work@gmail.com</a> へお送りください。</p><p>アプリは開発中で、機能はプラットフォームによって異なります。以下は現在のアプリとウェブサイトにおける情報の取り扱いです。アプリの利用にアカウント登録は必要ありません。</p><h2 id="端末に保存するデータ" tabindex="-1">端末に保存するデータ <a class="header-anchor" href="#端末に保存するデータ" aria-label="Permalink to &quot;端末に保存するデータ&quot;">​</a></h2><p>設定を記憶し、各機能を提供するため、アプリは端末内にデータを保存します。利用するプラットフォームと機能に応じて、次の内容が含まれます。</p><ul><li>選択した作品、言語、表示などの設定。</li><li>検索履歴と、画面の状態を復元するための情報。</li><li>お気に入りのモンスター、装備などの図鑑項目。</li><li>保存した装備セット、自分で付けた名前、装飾品の数、護石や防具の所持情報。</li></ul><p>これらは閲覧、検索、お気に入り、装備の検討に使います。アプリが開発者へアップロードすることはなく、開発者が運営するアカウントやクラウド同期サービスもありません。</p><h2 id="権限と自動収集" tabindex="-1">権限と自動収集 <a class="header-anchor" href="#権限と自動収集" aria-label="Permalink to &quot;権限と自動収集&quot;">​</a></h2><p>現在のアプリには、広告、追跡、利用状況の分析、クラッシュ情報の自動送信を行う SDK を組み込んでいません。現在の機能は連絡先、位置情報、カメラ、マイク、写真ライブラリへのアクセスを求めず、広告識別子も収集しません。</p><p>OS やアプリストアは、それぞれの設定とポリシーに基づき、インストールや診断に関する情報を別途処理する場合があります。プラットフォームから診断情報が提供された場合は、アプリの問題調査に使用します。</p><h2 id="お問い合わせで受け取る情報" tabindex="-1">お問い合わせで受け取る情報 <a class="header-anchor" href="#お問い合わせで受け取る情報" aria-label="Permalink to &quot;お問い合わせで受け取る情報&quot;">​</a></h2><p>メールでお問い合わせいただくと、送信元のメールアドレス、本文、ご自身で添付したファイルを受け取ります。これらは返信、問題の調査、プライバシーに関するご依頼への対応に使用します。必要な情報だけをお送りください。お問い合わせの内容を広告やメール配信リストに利用することはありません。</p><h2 id="ウェブサイト、バックアップ、外部サービス" tabindex="-1">ウェブサイト、バックアップ、外部サービス <a class="header-anchor" href="#ウェブサイト、バックアップ、外部サービス" aria-label="Permalink to &quot;ウェブサイト、バックアップ、外部サービス&quot;">​</a></h2><p><strong>ウェブサイト。</strong> このサイトは GitHub Pages で配信しています。アクセス解析、広告用 Cookie、追跡ピクセルは追加していません。サイト内検索はブラウザ内で動作し、表示や検索の設定がブラウザに保存される場合があります。アクセス時には GitHub が IP アドレスやブラウザ情報などの技術的なリクエスト情報を受け取ります。詳しくは <a href="https://docs.github.com/en/site-policy/privacy-policies/github-general-privacy-statement" target="_blank" rel="noreferrer">GitHub のプライバシー声明</a>をご確認ください。</p><p><strong>端末のバックアップ。</strong> OS の設定によって、アプリのデータが端末やクラウドのバックアップに含まれる場合があります。バックアップは各プラットフォーム事業者が管理しており、私たちが代わりに読み取ったり削除したりすることはできません。</p><p><strong>メールと外部リンク。</strong> お問い合わせ窓口には Gmail を使用しています。Google は <a href="https://policies.google.com/privacy" target="_blank" rel="noreferrer">Google のプライバシーポリシー</a>に基づいて、メールサービスの提供に必要な情報を処理します。外部サイトやアプリストアを開くと、それぞれのポリシーが適用されます。ホスティング、メール、バックアップの事業者が、お住まいの国以外で情報を処理する場合もあります。</p><h2 id="情報の共有、保存期間、削除" tabindex="-1">情報の共有、保存期間、削除 <a class="header-anchor" href="#情報の共有、保存期間、削除" aria-label="Permalink to &quot;情報の共有、保存期間、削除&quot;">​</a></h2><p>個人情報を販売・貸与したり、広告のために共有したりすることはありません。お送りいただいたメールは、上記のメール事業者を通じて処理されます。法律で求められる場合や、ご本人から明確な依頼がある場合には、実際に保有する情報を提供することがあります。</p><ul><li><strong>アプリ内のデータ：</strong> アプリの削除機能や端末の設定から消去できます。端末内のデータを消去するには、アプリとデータを両方削除する操作を選んでください。データを残してアプリだけを取り除く操作やアーカイブでは、データが保持される場合があります。バックアップは別に管理する必要があり、再インストール時にデータが復元される場合もあります。</li><li><strong>ウェブサイトの設定：</strong> このサイトの保存データをご自身で消去するか、ブラウザが消去するまで保持されます。</li><li><strong>メールや共有された診断情報：</strong> お問い合わせへの対応、追加調査、法的義務に必要な期間のみ保持します。法律上の保存義務がある場合を除き、お送りいただいた情報の削除を依頼できます。</li><li><strong>事業者が保有するデータ：</strong> バックアップやアクセスログなどは、その事業者の保存ルールと管理機能に従います。</li></ul><p>お送りいただいた情報の確認、訂正、削除は、下記の窓口へご連絡ください。端末内にしか存在しない記録を、私たちが遠隔で読み取ったり削除したりすることはできません。</p><h2 id="安全対策" tabindex="-1">安全対策 <a class="header-anchor" href="#安全対策" aria-label="Permalink to &quot;安全対策&quot;">​</a></h2><p>端末内のデータは、OS が提供するアプリ用ストレージの保護を利用します。このサイトは HTTPS で配信します。お問い合わせメールへのアクセスはサポートとプライバシー対応のために行い、メール事業者の安全対策を利用します。</p><h2 id="お子様のプライバシー" tabindex="-1">お子様のプライバシー <a class="header-anchor" href="#お子様のプライバシー" aria-label="Permalink to &quot;お子様のプライバシー&quot;">​</a></h2><p>アプリの利用に個人プロフィールや生年月日の入力は必要なく、お子様から意図的に個人情報を求めることもありません。お子様が個人情報を送信したと思われる場合は、保護者の方からご連絡ください。削除について対応します。</p><h2 id="ポリシーの変更" tabindex="-1">ポリシーの変更 <a class="header-anchor" href="#ポリシーの変更" aria-label="Permalink to &quot;ポリシーの変更&quot;">​</a></h2><p>取り扱いが変わる場合は、このページと日付を更新します。重要な変更はウェブサイトやアプリの更新情報でお知らせします。新しい機能で権限や同意が必要になった場合は、その操作時に別途確認します。このポリシーだけで同意があったとは扱いません。</p><h2 id="お問い合わせ" tabindex="-1">お問い合わせ <a class="header-anchor" href="#お問い合わせ" aria-label="Permalink to &quot;お問い合わせ&quot;">​</a></h2><p>開発者：<strong>eurekaffeine（刘耀晨）</strong><br> アプリ：<strong>Sapphire Star Codex / 青い星のハンターノート</strong><br> メール：<a href="mailto:eurekaffeine.work@gmail.com" target="_blank" rel="noreferrer">eurekaffeine.work@gmail.com</a></p>',29)])])}const f=e(i,[["render",n]]);export{u as __pageData,f as default};
